import { Page, Locator } from '@playwright/test';

export class LoginPage {
    private readonly page: Page;

    // Locators
    private readonly headingReturningCustomer: Locator;
    private readonly txtEmail: Locator;
    private readonly txtPassword: Locator;
    private readonly btnLogin: Locator;
    private readonly msgError: Locator;

    constructor(page: Page) {
        this.page = page;

        // Initialize locators with CSS selectors
        this.headingReturningCustomer = page.getByRole('heading', { name: 'Returning Customer' });
        this.txtEmail = page.getByLabel('E-Mail Address');
        this.txtPassword = page.getByLabel('Password');
        this.btnLogin = page.getByRole('button', { name: 'Login' });
        this.msgError = page.locator('.alert-danger');
    }

    /**
     * Verifies the login page is displayed
     * @returns Promise<boolean> - true if the "Returning Customer" section is displayed
     */
    async isLoginPageExists(): Promise<boolean> {
        try {
            await this.headingReturningCustomer.waitFor({ state: 'visible' });
            return true;
        } catch (error) {
            console.log(`Error checking login page: ${error}`);
            return false;
        }
    }

    /**
     * Fills the email address
     * @param email - Email address
     */
    async setEmail(email: string): Promise<void> {
        await this.txtEmail.fill(email);
    }

    /**
     * Fills the password
     * @param password - Password
     */
    async setPassword(password: string): Promise<void> {
        await this.txtPassword.fill(password);
    }

    /**
     * Clicks the Login button
     */
    async clickLogin(): Promise<void> {
        await this.btnLogin.click();
    }

    /**
     * Logs in with the given credentials
     * @param email - Email address
     * @param password - Password
     */
    async login(email: string, password: string): Promise<void> {
        try {
            await this.setEmail(email);
            await this.setPassword(password);
            await this.clickLogin();
        } catch (error) {
            console.log(`Error during login: ${error}`);
            throw error;
        }
    }

    /**
     * Gets the login warning/error message
     * @returns Promise<string> - Warning text shown after a failed login
     */
    async getLoginErrorMessage(): Promise<string> {
        await this.msgError.waitFor({ state: 'visible' });
        return (await this.msgError.textContent())?.trim() ?? '';
    }
}
